function booleanProduct(A, B) {
  function shape(M) {
    if (!Array.isArray(M) || M.length === 0 || !Array.isArray(M[0]) || M[0].length === 0) throw new TypeError("Nonempty rectangular bit matrix required");
    const width = M[0].length;
    for (const row of M) {
      if (!Array.isArray(row) || row.length !== width) throw new TypeError("Ragged matrix");
      for (const bit of row) if (bit !== 0 && bit !== 1) throw new TypeError("Numeric bits required");
    }
    return [M.length, width];
  }
  const [m, k] = shape(A), [rows, n] = shape(B);
  if (k !== rows) throw new RangeError("Inner dimensions must match");
  const C = Array.from({length: m}, () => Array(n).fill(0));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      for (let t = 0; t < k; t++) {
        if (A[i][t] === 1 && B[t][j] === 1) { C[i][j] = 1; break; }
      }
    }
  }
  return C;
}
